import{_ as r,o as n,c as a,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const f=JSON.parse('{"title":"Frühere Korrektur der EP-Jahre für die Kompetenzzuordnung","description":"","frontmatter":{"title":"Frühere Korrektur der EP-Jahre für die Kompetenzzuordnung","source_pageid":361,"source_revision":6062},"headers":[],"relativePath":"hilfe/fruehere-verfahren/ep-jahre-kompetenzzuordnung.md","filePath":"hilfe/fruehere-verfahren/ep-jahre-kompetenzzuordnung.md"}'),t={name:"hilfe/fruehere-verfahren/ep-jahre-kompetenzzuordnung.md"};function u(h,e,s,d,l,o){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="fruhere-korrektur-der-ep-jahre-fur-die-kompetenzzuordnung" tabindex="-1">Frühere Korrektur der EP-Jahre für die Kompetenzzuordnung <a class="header-anchor" href="#fruhere-korrektur-der-ep-jahre-fur-die-kompetenzzuordnung" aria-label="Permalink to &quot;Frühere Korrektur der EP-Jahre für die Kompetenzzuordnung&quot;">​</a></h1><p>Dieser Artikel beschreibt einen früheren Sonderfall bei der Zuordnung von Ankreuzkompetenzen. Die damalige Anleitung arbeitete mit einer Korrektur des Feldes <strong>EP-Jahre</strong> unter <strong>Individualdaten II</strong>.</p><p>Für die heutige Erfassung beachten Sie <a href="/schild3/schueler/eintragung-der-ep-jahre-tutorial.html">Die Jahre der Schuleingangsphase eintragen</a>. Die aktuelle Anleitung zu den Zeugnissen finden Sie unter <a href="/zeugnisse/grundschule/grundschulzeugnisse-ankreuzzeugnis-tutorial.html">Ankreuzzeugnisse für die Grundschule erstellen</a>.</p><h2 id="der-fruhere-sonderfall" tabindex="-1">Der frühere Sonderfall <a class="header-anchor" href="#der-fruhere-sonderfall" aria-label="Permalink to &quot;Der frühere Sonderfall&quot;">​</a></h2><p>Nach einem Rücktritt in der Schuleingangsphase konnte ein Kind die erste Klasse besuchen, obwohl es bereits dem damaligen Jahrgang <strong>E2</strong> zugeordnet war. Dadurch wurden die Kompetenzbeschreibungen des zweiten Jahrgangs herangezogen, obwohl die Beschreibungen für die erste Klasse benötigt wurden.</p><h2 id="damalige-korrektur" tabindex="-1">Damalige Korrektur <a class="header-anchor" href="#damalige-korrektur" aria-label="Permalink to &quot;Damalige Korrektur&quot;">​</a></h2><p>Die Wiki-Anleitung beschrieb hierfür folgende Schritte:</p><ol><li>Unter <strong>Individualdaten II</strong> im Feld <strong>EP-Jahre</strong> den Wert <strong>1</strong> eintragen.</li><li>Nach dem späteren Wechsel in die zweite Klasse den Wert <strong>3</strong> eintragen.</li></ol><p>Dies ist der frühere Arbeitsweg. Die heutige Zuordnung von Statistikjahrgang und EP-Jahr ist in der <a href="/schild3/schueler/eintragung-der-ep-jahre-tutorial.html">aktuellen Anleitung zu den EP-Jahren</a> beschrieben.</p><h2 id="bedeutung-fur-die-weitere-schullaufbahn" tabindex="-1">Bedeutung für die weitere Schullaufbahn <a class="header-anchor" href="#bedeutung-fur-die-weitere-schullaufbahn" aria-label="Permalink to &quot;Bedeutung für die weitere Schullaufbahn&quot;">​</a></h2><p>Der damalige Hinweis bezeichnete den Wert als nicht statistikrelevant, wies aber auf seine Berücksichtigung bei der Berechnung der Schulbesuchsjahre hin. Der Verbleib in der Schuleingangsphase musste deshalb korrekt erfasst und an weiterführende Schulen kommuniziert werden, da er sich auf das Ende der Vollzeitschulpflicht auswirken konnte.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Grundschulzeugnisse_Ankreuzzeugnis_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6062.</p>',13)])])}const c=r(t,[["render",u]]);export{f as __pageData,c as default};
